import React, { useState } from "react";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { db } from "../../firebase";
import { calculateCarbonMetrics } from "../../utils/carbonCalculator";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Alert,
} from "reactstrap";
import UserHeader from "components/Headers/UserHeader.js";

const CarbonInputPage = () => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split("T")[0],
    electricity: "",
    naturalGas: "",
    vehicleMiles: "",
    airTravel: "",
    wasteProduced: "",
    recycling: "",
    waterUsage: "",
    notes: "",
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: "", text: "" });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ type: "", text: "" });

    try {
      // Convert input values to numbers
      const inputData = Object.keys(formData).reduce((acc, key) => {
        if (key !== "date") {
          acc[key] = parseFloat(formData[key]) || 0;
        }
        return acc;
      }, {});

      const selectedDate = new Date(formData.date);
      const createdAt = Timestamp.fromDate(selectedDate);

      // Calculate carbon footprint and credits
      const carbonData = calculateCarbonMetrics(inputData);

      // Debugging: Log calculation result
      console.log("🛠 Debug carbonData:", carbonData);

      // Ensure credits is a valid number
      const credits = parseFloat(carbonData.credits) || 0;
      if (isNaN(credits)) {
        throw new Error("Calculated credits is NaN or undefined.");
      }

      // Debugging: Log final data before saving
      console.log("🔥 Data being saved to Firestore:", {
        ...inputData,
        totalCarbon: carbonData.totalCarbon,
        credits: credits,
        progress: carbonData.progress,
        rank: carbonData.rank,
        createdAt,
      });

      // Save to Firestore
      await addDoc(collection(db, "carbonFootprint"), {
        ...inputData,
        totalCarbon: carbonData.totalCarbon,
        credits,
        progress: carbonData.progress,
        rank: carbonData.rank,
        createdAt,
      });

      setMessage({ type: "success", text: "Data saved successfully!" });
    } catch (error) {
      console.error("❌ Error saving data:", error);
      setMessage({ type: "danger", text: "Failed to save data. Try again." });
    }

    setLoading(false);
  };

  return (
    <>
      <UserHeader />
      <Container className="mt--7" fluid>
        <Row>
          <Col className="order-xl-1" xl="12">
            <Card className="bg-secondary shadow">
              <CardHeader className="bg-white border-0">
                <Row className="align-items-center">
                  <Col xs="8">
                    <h3 className="mb-0">Carbon Input Form</h3>
                  </Col>
                  <Col className="text-right" xs="4">
                    <Button color="primary" onClick={handleSubmit} size="sm">
                      {loading ? "Saving..." : "Submit"}
                    </Button>
                  </Col>
                </Row>
              </CardHeader>
              <CardBody>
                {message.text && <Alert color={message.type}>{message.text}</Alert>}

                <Form onSubmit={handleSubmit}>
                  {/* Date Picker */}
                  <h6 className="heading-small text-muted mb-4">Date of Entry</h6>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="date">Date</label>
                        <Input
                          type="date"
                          name="date"
                          value={formData.date}
                          onChange={handleChange}
                          required
                        />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Energy Usage */}
                  <h6 className="heading-small text-muted mb-4">Energy Usage</h6>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="electricity">Electricity (kWh)</label>
                        <Input type="number" name="electricity" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="naturalGas">Natural Gas (therms)</label>
                        <Input type="number" name="naturalGas" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Transportation */}
                  <h6 className="heading-small text-muted mb-4">Transportation</h6>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="vehicleMiles">Vehicle Miles (miles)</label>
                        <Input type="number" name="vehicleMiles" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="airTravel">Air Travel (miles)</label>
                        <Input type="number" name="airTravel" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Waste Management */}
                  <h6 className="heading-small text-muted mb-4">Waste Management</h6>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="wasteProduced">Waste (kg)</label>
                        <Input type="number" name="wasteProduced" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="recycling">Recycling (kg)</label>
                        <Input type="number" name="recycling" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Water Usage */}
                  <h6 className="heading-small text-muted mb-4">Water Usage</h6>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <label htmlFor="waterUsage">Water Usage (liters)</label>
                        <Input type="number" name="waterUsage" onChange={handleChange} required />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Notes */}
                  <h6 className="heading-small text-muted mb-4">Additional Notes</h6>
                  <Row>
                    <Col md="12">
                      <FormGroup>
                        <label htmlFor="notes">Notes</label>
                        <Input type="textarea" name="notes" onChange={handleChange} rows="4" />
                      </FormGroup>
                    </Col>
                  </Row>

                  {/* Submit Button */}
                  <Button color="primary" type="submit" disabled={loading}>
                    {loading ? "Saving..." : "Submit"}
                  </Button>
                </Form>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default CarbonInputPage;
